export class DeployService {
  constructor(private readonly fs: FilesystemRepository) {}

  async deploy(
    featureName: FeatureName,
    skillSourceDir: string,
  ): Promise<Result<DeployResult>> {
    const destinations = [
      join('.claude', 'skills', featureName),
      join('.cursor', 'skills', featureName),
      join('.agents', 'skills', featureName),
    ];

    const deployedPaths: string[] = [];

    for (const dest of destinations) {
      const ensureResult = await this.fs.ensureDir(dest);
      if (!ensureResult.ok) return ensureResult;

      const copyResult = await this.fs.copy(skillSourceDir, dest);
      if (!copyResult.ok) return copyResult;

      deployedPaths.push(dest);
    }

    return ok({ deployedPaths });
  }

  async skillDirExists(featureName: FeatureName): Promise<boolean> {
    const skillDir = join('.features', featureName, 'skill');
    return this.fs.isDirectory(skillDir);
  }
}

  const skillExists = await deployService.skillDirExists(featureName);
  if (!skillExists) {
    showError('Skill directory not found. Skipping deployment.');
    showOutro(`Partially created at .features/${featureName}/`);
    return;
  }

  showDaatIntro();
  showInfo('Deploying feature to code agents...');
  console.log();

  const skillDir = join('.features', featureName, 'skill');
  const deployResult = await deployService.deploy(featureName, skillDir);
  if (!deployResult.ok) {
    showError(`Deployment failed: ${deployResult.error.message}`);
    showOutro(`Skill saved at .features/${featureName}/skill/ — deploy manually.`);
    return;
  }

  showDaatNote(featureName);
  showInfo(`Run ${chalk.hex('#7B68EE').bold('features implement')} to implement.`);
  showOutro(`${featureName} is ready.`);
}

const cwd = process.cwd();
const fs = new FilesystemRepository(cwd);
const featureRepo = new FeatureRepository(fs);
const claudeClient = new ClaudeClient();
const gitClient = new GitClient(cwd);
const editorClient = new EditorClient();

const featureService = new FeatureService(featureRepo, claudeClient);
const kbService = new KBService(fs, claudeClient);
const skillService = new SkillService(fs, claudeClient, gitClient);
const deployService = new DeployService(fs);

const analyzeService = new AnalyzeService(fs, gitClient, claudeClient);
const validateService = new ValidateService(fs);
const compileService = new CompileService(fs, gitClient, validateService);
const serveService = new ServeService(fs, VIEWER_DIST_DIR);
const liveServerService = new LiveServerService(fs, analyzeService, compileService, VIEWER_DIST_DIR);

const createCommand = makeCreateCommand({ kbService, skillService, deployService, editorClient });
const implementCommand = makeImplementCommand({ featureService, kbService, skillService, deployService, editorClient });
const initCommand = makeInitCommand({ analyzeService, compileService, gitClient, fs, rootDir: cwd });
const syncCommand = makeSyncCommand({ analyzeService, compileService });
const serveCommand = makeServeCommand({ serveService, liveServerService });

export function makeInitCommand(deps: InitDeps) {
  const { analyzeService, compileService, gitClient, fs, rootDir } = deps;

  return async function initCommand(options: InitOptions): Promise<void> {
    showAnalyzeIntro('init');
    await migrateFromCodeExplain(fs);
    const model = resolveModel(options.model, 'claude-opus-4-6');
    showInfo(`Model: ${model}`);
    const useCache = options.cache !== false;
    analyzeService.resetStats();

    let inventory: InventoryEntry[] = [];

    if (options.feature) {
      const existing = await analyzeService.readInventory();
      if (!existing.ok) {
        showError(existing.error.message);
        process.exitCode = 1;
        return;
      }
      const entry = existing.value.find((e) => e.id === options.feature);
      if (!entry) {
        showError(`Feature "${options.feature}" is not in the inventory. Known ids: ${existing.value.map((e) => e.id).join(', ')}`);
        process.exitCode = 1;
        return;
      }
      inventory = [entry];
    } else {
      let resumed = false;
      if (useCache) {
        const existing = await analyzeService.readInventory();
        if (existing.ok) {
          inventory = existing.value;
          resumed = true;
          showSuccess(`Resuming from previous inventory (${inventory.length} features). Use --no-cache to re-discover.`);
        }
      }

      if (!resumed) {
        while (true) {
          const ac = new AbortController();
          const sigintHandler = () => { ac.abort(); };
          process.on('SIGINT', sigintHandler);

          const spin = createSpinner();
          spin.start('Pass 1/2 — discovering areas and features…');
          const result = await analyzeService.runInventory(model, QUIET, ac.signal);

          process.off('SIGINT', sigintHandler);

          if (result.ok) {
            spin.stop('Inventory complete.');
            inventory = result.value;
            showSuccess(`Inventory: ${inventory.length} feature(s) across the repo.`);
            break;
          }
          if (result.error.code === 'CLAUDE_ABORTED') {
            spin.stop('Paused.');
            showInfo('Press Enter to resume (Ctrl+C to exit)…');
            await waitForEnterOrExit();
            showInfo('Retrying inventory…');
            continue;
          }
          if (result.error.code === 'CLAUDE_RATE_LIMITED') {
            spin.stop('Quota reached.');
            showWarn(`Usage limit reached: ${result.error.message}`);
            showInfo('Press Enter to retry when your quota resets (Ctrl+C to exit)…');
            await waitForEnterOrExit();
            showInfo('Retrying inventory…');
            continue;
          }
          // Genuine failure — surface it and stop, rather than looping as if it were a quota reset.
          spin.stop('Failed.');
          showError(`Inventory failed: ${result.error.message}`);
          process.exitCode = 1;
          return;
        }

export function makeServeCommand(deps: ServeDeps) {
  const { serveService, liveServerService } = deps;

  return async function serveCommand(options: ServeOptions): Promise<void> {
    showAnalyzeIntro(options.live ? 'serve --live' : 'serve');

    const port = Number(options.port ?? DEFAULT_SERVE_PORT);
    const result = options.live
      ? liveServerService.start(port, resolveModel(options.model, 'sonnet'))
      : serveService.start(port);
    if (!result.ok) {
      showError(result.error.message);
      process.exitCode = 1;
      return;
    }

    showInfo(`Browsing at ${chalk.bold(`http://localhost:${port}`)} — press Ctrl-C to stop.`);
    if (options.live) showInfo('Live mode: trigger re-analysis from the UI.');
  };
}

export function makeCreateCommand(deps: CreateFlowDeps) {
  return async function createCommand(topic: string | undefined, options: CreateFlowOptions): Promise<void> {
    await createFeatureFlow(deps, topic, options);
  };
}

