export async function createFeatureFlow(
  deps: CreateFlowDeps,
  topic: string | undefined,
  options: CreateFlowOptions,
): Promise<void> {
  const { kbService, skillService, deployService, editorClient } = deps;

  showIntro();

  let finalTopic = topic;
  if (!finalTopic) {
    const result = await askTopic();
    if (isCancelled(result)) {
      showOutro('Cancelled.');
      return;
    }
    finalTopic = result;
  }

  const suggested = deriveFeatureName(finalTopic);
  const nameResult = await askFeatureName(suggested);
  if (isCancelled(nameResult)) {
    showOutro('Cancelled.');
    return;
  }
  const featureName: FeatureName = toFeatureName(nameResult);
  const model: ClaudeModel = resolveModel(options.model, DEFAULT_MODEL);

  showFeatureFolder(join('.features', featureName));

  const spin = createSpinner();
  spin.start('Installing dependencies...');

  const installResult = await skillService.ensureSkillCreator();
  if (!installResult.ok) {
    spin.stop('Failed to install dependencies.');
    handleError(installResult.error);
    return;
  }
  spin.stop('Dependencies ready.');

  showInfo('Launching Claude Code with KB creator...');
  console.log();

  const kbResult = await kbService.createKB(featureName, finalTopic, model);
  if (!kbResult.ok) {
    console.log();
    handleError(kbResult.error);
    showOutro(`Partial feature at .features/${featureName}/`);
    return;
  }

  console.log();
  showKbNote(kbResult.value);

  while (true) {
    const review = await askKbReview(kbResult.value);

    if (isCancelled(review) || review === 'skip') {
      showInfo('Skill creation skipped. Re-run `features create` when you want the skill.');
      showOutro(`KB saved at .features/${featureName}/`);
      return;
    }

    if (review === 'edit') {
      const editResult = await editorClient.open(kbResult.value);
      if (!editResult.ok) {
        showError(`${editResult.error.message}. Set $EDITOR and try again, or edit the file manually.`);
      }
      continue;
    }

    break;
  }

  showInfo('Launching Claude Code with Skill creator...');
  console.log();

  const skillResult = await skillService.createSkill({
    featureName,
    topic: finalTopic,
    kbPath: kbResult.value,
    model,
  });

  console.log();
  if (!skillResult.ok) {
    handleError(skillResult.error);
    showOutro(`Skill creation failed. KB was saved.`);
    return;
  }

  if (skillResult.value !== 0) {
    showOutro(`Skill creation exited with code ${skillResult.value}. KB was saved.`);
    return;
  }

  const skillExists = await deployService.skillDirExists(featureName);
  if (!skillExists) {
    showError('Skill directory not found. Skipping deployment.');
    showOutro(`Partially created at .features/${featureName}/`);
    return;
  }

  showDaatIntro();
  showInfo('Deploying feature to code agents...');
  console.log();

  const skillDir = join('.features', featureName, 'skill');
  const deployResult = await deployService.deploy(featureName, skillDir);
  if (!deployResult.ok) {
    showError(`Deployment failed: ${deployResult.error.message}`);
    showOutro(`Skill saved at .features/${featureName}/skill/ — deploy manually.`);
    return;
  }

  showDaatNote(featureName);
  showInfo(`Run ${chalk.hex('#7B68EE').bold('features implement')} to implement.`);
  showOutro(`${featureName} is ready.`);
}

export class KBService {
  constructor(
    private readonly fs: FilesystemRepository,
    private readonly claudeClient: ClaudeClient,
  ) {}

  async createKB(
    featureName: FeatureName,
    topic: string,
    model: ClaudeModel,
  ): Promise<Result<string>> {
    const kbDir = join('.features', featureName, 'kb');
    const ensureResult = await this.fs.ensureDir(kbDir);
    if (!ensureResult.ok) return ensureResult;

    const kbFilePath = join('.features', featureName, 'kb', 'KNOWLEDGE.md');
    const userMessage = `Create a knowledge file for: ${topic}\n\nWrite the output to: ${kbFilePath}`;

    const claudeResult = await this.claudeClient.execute({
      systemPromptFile: KB_PROMPT_PATH,
      userPrompt: userMessage,
      model,
      print: true,
    });

    if (!claudeResult.ok) return claudeResult;

    if (claudeResult.value.exitCode !== 0) {
      return fail('CLAUDE_FAILED', `Claude exited with code ${claudeResult.value.exitCode}`);
    }

    const kbExists = await this.fs.exists(kbFilePath);
    if (!kbExists) {
      return fail('KB_NOT_FOUND', 'KB was not created by Claude');
    }

    return ok(kbFilePath);
  }

}

async runCombinedFeature(entry: InventoryEntry, model: ClaudeModel, onProgress?: ProgressObserver, signal?: AbortSignal, settingsJson?: string): Promise<Result<void>> {
  const sha = await this.git.headSha();
  if (!sha.ok) return sha;

  const hasCodegraph = await this.fs.exists('.codegraph');
  const maxTurns = turnCapFor(entry.complexity);

  const featureFile = `${ANALYSIS_FEATURES_DIR}/${entry.id}.md`;
  const absFeatureFile = this.abs(featureFile);
  const skillFile = `${SKILLS_DIR}/${entry.id}.md`;
  const featureContext = this.repoMap
    ? await buildFeatureContext(entry, this.repoMap, async (p) => {
        const r = await this.fs.readText(p);
        return r.ok ? r.value : undefined;
      })
    : '';
  const userPrompt = [
    `Deep-dive the ${entry.kind} feature "${entry.name}" (id: ${entry.id}) of this repository.`,
    `It belongs to area "${entry.area}". Its one-line summary from the inventory:`,
    `"${entry.summary}"`,
    ``,
    `Write the feature knowledge file to exactly this absolute path: ${absFeatureFile}`,
    this.PATH_GUARD,
    `Use this git sha for analyzedAt and every ref's sha field: ${sha.value}`,
    ``,
    `Feature ids that exist (for the related list): see ${this.abs(INVENTORY_FILE)}.`,
    ...(featureContext ? ['', featureContext] : []),
  ].join('\n');

  const run = await this.claude.execute({
    systemPromptFile: COMBINED_PROMPT_PATH,
    userPrompt,
    model,
    print: true,
    cwd: this.fs.root,
    onEvent: this.claudeObserver(onProgress),
    // Stable across all feature calls → preserves Claude prompt-cache hits. Per-feature context goes in userPrompt.
    appendSystemPrompt: hasCodegraph ? CODEGRAPH_ADDENDUM : undefined,
    signal,
    maxTurns,
    settingsJson,
  });
  if (!run.ok) return run;
  this.trackCall(run.value);

  // Generate skill deterministically from the parsed knowledge file
  await this.renderAndWriteSkill(entry, featureFile, skillFile);

  for (let attempt = 0; ; attempt++) {
    const featureIssues = await this.featureProblems(featureFile, entry);
    if (featureIssues.length === 0) {
      // Re-render skill after a successful repair (knowledge file just changed)
      await this.renderAndWriteSkill(entry, featureFile, skillFile);
      return ok(undefined);
    }

    const allProblems = featureIssues.map(
      (i) => `${absFeatureFile}: ${i.code}: ${i.message}${i.line !== undefined ? ` (line ${i.line})` : ''}`,
    );

    if (attempt >= MAX_REPAIRS) {
      return fail(
        'ANALYSIS_FAILED',
        `${entry.id} is invalid after ${MAX_REPAIRS} repairs:\n${allProblems.map((p) => `- ${p}`).join('\n')}`,
      );
    }
    onProgress?.({ kind: 'warn', message: `${entry.id} has ${featureIssues.length} validation problem(s) — repairing…` });
    const repair = await this.claude.execute({
      systemPromptFile: COMBINED_PROMPT_PATH,
      userPrompt: [
        `Your previous output at ${absFeatureFile} has validation errors. Fix the file in place. Errors:`,
        ...allProblems.map((p) => `- ${p}`),
      ].join('\n'),
      model,
      print: true,
      cwd: this.fs.root,
      onEvent: this.claudeObserver(onProgress),
      signal,
    });
    if (!repair.ok) return repair;
    this.trackCall(repair.value, true);
  }
}

export class SkillService {
  constructor(
    private readonly fs: FilesystemRepository,
    private readonly claudeClient: ClaudeClient,
    private readonly gitClient: GitClient,
  ) {}

  async ensureSkillCreator(): Promise<Result<void>> {
    const installPath = join(SKILL_CREATOR_INSTALL_DIR, 'SKILL.md');
    if (this.fs.existsSync(installPath)) {
      return ok(undefined);
    }

    const installDir = this.fs.resolve(SKILL_CREATOR_INSTALL_DIR);
    const tmpDir = join(tmpdir(), `features-skill-creator-${Date.now()}`);

    try {
      const sparseResult = await this.gitClient.sparseClone(SKILL_CREATOR_REPO, SKILL_CREATOR_SUBPATH, tmpDir);

      if (!sparseResult.ok) {
        await this.fs.removeAbsolute(tmpDir);
        const shallowResult = await this.gitClient.shallowClone(SKILL_CREATOR_REPO, tmpDir);
        if (!shallowResult.ok) return shallowResult;
      }

      const srcDir = join(tmpDir, SKILL_CREATOR_SUBPATH);
      const ensureResult = await this.fs.ensureDir(SKILL_CREATOR_INSTALL_DIR);
      if (!ensureResult.ok) return ensureResult;

      const copyResult = await this.fs.copyAbsolute(srcDir, installDir);
      if (!copyResult.ok) return copyResult;

      return ok(undefined);
    } finally {
      await this.fs.removeAbsolute(tmpDir);
    }
  }

  async createSkill(options: CreateSkillOptions): Promise<Result<number>> {
    const { featureName, topic, kbPath, model } = options;

    const installResult = await this.ensureSkillCreator();
    if (!installResult.ok) return installResult;

    const skillDir = join('.features', featureName, 'skill');
    const ensureResult = await this.fs.ensureDir(skillDir);
    if (!ensureResult.ok) return ensureResult;

    const userMessage = [
      `/skill-creator Create a skill for "${topic}" based on the knowledge file at ${kbPath}.`,
      '',
      `Place ALL output (SKILL.md, scripts/, agents/, references/, everything) inside ${skillDir}/`,
      '',
      `The knowledge file path for the Knowledge Sync feedback loop is: ${kbPath}`,
      '',
      'Do not ask me questions — read the knowledge file and create the skill.',
    ].join('\n');

    const result = await this.claudeClient.execute({
      appendSystemPromptFile: SKILL_CREATION_PROMPT_PATH,
      userPrompt: userMessage,
      model,
      print: true,
    });

    if (!result.ok) return result;
    return ok(result.value.exitCode);
  }

}

export function parseFeature(source: string): ParseResult<FeatureDoc> {
  const issues: Issue[] = [];

  const fm = parseFrontmatter(source);
  issues.push(...fm.issues);

  const fmResult = FeatureFrontmatterSchema.safeParse(fm.data);
  if (!fmResult.success) {
    for (const e of fmResult.error.issues) {
      issues.push(issue('bad-frontmatter', `frontmatter.${e.path.join('.')}: ${e.message}`));
    }
  }

  const tree = parseMarkdown(fm.body);
  const sections = new Map(splitSections(tree).map((s) => [s.title, s]));

  const missing = (title: string) =>
    issues.push(issue('missing-section', `Required section "## ${title}" is missing or empty`));

  // ## In a nutshell
  const nutshellSection = sections.get(FEATURE_SECTIONS.nutshell);
  const nutshell = nutshellSection ? sectionProse(nutshellSection.nodes) : '';
  if (!nutshell) missing(FEATURE_SECTIONS.nutshell);

  // ## How it works
  const howSection = sections.get(FEATURE_SECTIONS.howItWorks);
  const howItWorks = howSection ? sectionListItems(howSection.nodes).filter(Boolean) : [];
  if (howItWorks.length === 0) missing(FEATURE_SECTIONS.howItWorks);

  // ## Flow (optional)
  const flowSection = sections.get(FEATURE_SECTIONS.flow);
  const flow = flowSection ? sectionListItems(flowSection.nodes).filter(Boolean).map(parseFlowStep) : [];

  // ## Code references
  const refsSection = sections.get(FEATURE_SECTIONS.refs);
  const refs: CodeRef[] = [];
  if (!refsSection) {
    missing(FEATURE_SECTIONS.refs);
  } else {
    const blocks = sectionCodeBlocks(refsSection.nodes, 'ref');
    if (blocks.length === 0) {
      issues.push(
        issue(
          'missing-refs',
          `Section "## ${FEATURE_SECTIONS.refs}" has no \`\`\`ref blocks`,
          refsSection.line + fm.bodyOffset,
        ),
      );
    }
    for (const block of blocks) {
      const refResult = parseRefBlock(block.value, block.line + fm.bodyOffset);
      if (refResult.ok) refs.push(refResult.doc);
      else issues.push(...refResult.issues);
    }
  }

  if (issues.length > 0) return failed(issues);

  return parsed({
    frontmatter: fmResult.success ? fmResult.data : (undefined as never),
    nutshell,
    howItWorks,
    flow,
    refs,
  });
}

export function makeSyncCommand(deps: SyncDeps) {
  const { analyzeService, compileService } = deps;

  return async function syncCommand(options: SyncOptions): Promise<void> {
    showAnalyzeIntro('sync');

    const before = await analyzeService.readInventory();
    if (!before.ok) {
      showError(before.error.message);
      showOutro();
      return;
    }

    const model = resolveModel(options.model, 'claude-opus-4-6');
    const concurrency = Math.max(1, parseInt(options.concurrency ?? '', 10) || DEFAULT_CONCURRENCY);
    const knownIds = new Set(before.value.map((f) => f.id));
    analyzeService.resetStats();

    const spin = createSpinner();
    spin.start('Scanning repository for new features…');
    const inventoryResult = await analyzeService.runInventory(model, QUIET);
    spin.stop(inventoryResult.ok ? 'Scan complete.' : 'Scan failed.');
    if (!inventoryResult.ok) {
      showError(inventoryResult.error.message);
      showOutro();
      return;
    }

    const newFeatures = inventoryResult.value.filter((f) => !knownIds.has(f.id));
    const removed = before.value.filter((f) => !inventoryResult.value.some((next) => next.id === f.id));

    if (removed.length > 0) {
      showWarn(`No deletion performed for missing old feature(s): ${removed.map((f) => f.id).join(', ')}`);
    }

    if (newFeatures.length > 0) {
      showInfo(`Mapping ${newFeatures.length} new feature(s) with concurrency ${concurrency}…`);
      const progress = createProgressBar(newFeatures.length);
      const failures: string[] = [];

      await mapWithConcurrency(newFeatures, concurrency, async (entry: InventoryEntry) => {
        progress.update(entry.name);
        const result = await analyzeService.runCombinedFeature(entry, model, QUIET);
        if (!result.ok) failures.push(entry.id);
      });
      progress.done();

      if (failures.length > 0) showWarn(`${failures.length} feature(s) failed: ${failures.join(', ')}`);
      if (failures.length === newFeatures.length) {
        showError('No new feature files were produced.');
        showOutro();
        return;
      }
    } else {
      showSuccess('No new features found.');
    }

    showInfo('Compiling manifest…');
    const compiled = await compileService.compile();
    if (!compiled.ok) {
      showError(formatCompileError(compiled.error));
      showOutro();
      return;
    }

    showSuccess(`Compiled ${compiled.value.features} feature(s).`);
    showOutro(newFeatures.length > 0 ? `Mapped ${newFeatures.length} new feature(s): ${newFeatures.map((f) => f.id).join(', ')}` : 'Already in sync.');
  };
}

async readInventory(): Promise<Result<InventoryEntry[]>> {
  const raw = await this.fs.readText(INVENTORY_FILE);
  if (!raw.ok) return fail('ANALYSIS_FAILED', 'No inventory found — run `features init` first.');
  try {
    const parsed = InventorySchema.safeParse(JSON.parse(raw.value));
    if (!parsed.success) {
      return fail('ANALYSIS_FAILED', `_inventory.json does not match the schema: ${parsed.error.message}`);
    }
    return ok(parsed.data);
  } catch (e) {
    return fail('ANALYSIS_FAILED', `_inventory.json is not valid JSON: ${(e as Error).message}`, e);
  }
}

