export async function mapWithConcurrency<T, R>(
  items: readonly T[],
  concurrency: number,
  fn: (item: T, index: number) => Promise<R>,
  signal?: AbortSignal,
): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let nextIndex = 0;

  async function worker(): Promise<void> {
    while (nextIndex < items.length) {
      if (signal?.aborted) return;
      const i = nextIndex++;
      results[i] = await fn(items[i]!, i);
    }
  }

  const workers = Array.from({ length: Math.min(concurrency, items.length) }, () => worker());
  await Promise.all(workers);
  return results;
}

export function makeImplementCommand(deps: ImplementDeps) {
  const { featureService } = deps;

  return async function implementCommand(promptWords: string[] | undefined, options: CreateFlowOptions): Promise<void> {
    showImplementIntro();

    const model: ClaudeModel = resolveModel(options.model, DEFAULT_MODEL);
    const prompt = promptWords?.join(' ').trim();

    if (prompt) {
      const result = await featureService.implementTask(prompt, model);
      if (!result.ok && result.error.code !== 'CLAUDE_ABORTED') {
        showError(result.error.message);
        showOutro();
        return;
      }

      const create = await askCreateFeatureFromImplementation();
      if (isCancelled(create)) {
        showOutro('Done.');
        return;
      }
      if (create) {
        await createFeatureFlow(deps, prompt, options);
        return;
      }
      showOutro('Done.');
      return;
    }

    const featuresResult = await featureService.listFeatures();
    if (!featuresResult.ok) {
      showError(featuresResult.error.message);
      showOutro();
      return;
    }

    const features = featuresResult.value;

    if (features.length === 0) {
      showError('No features found. Run `features implement <task>` or `features create` first.');
      showOutro();
      return;
    }

    let selectedName: string;

    if (features.length === 1) {
      selectedName = features[0].name;
      showInfo(`Using ${selectedName}`);
    } else {
      const result = await askSelectFeature(features);
      if (isCancelled(result)) {
        showOutro('Cancelled.');
        return;
      }
      selectedName = result;
    }

    const selected = features.find((f) => f.name === selectedName);
    if (!selected) {
      showError(`Feature "${selectedName}" not found.`);
      showOutro();
      return;
    }

    const taskResult = await askRunTask(selected);
    if (isCancelled(taskResult)) {
      showOutro('Cancelled.');
      return;
    }

    const result = await featureService.executeFeature(selected, taskResult, model);
    if (!result.ok && result.error.code !== 'CLAUDE_ABORTED') {
      showError(result.error.message);
      showOutro();
    }
  };
}

async executeFeature(feature: Feature, task: string, model: ClaudeModel): Promise<Result<void>> {
  const kbResult = await this.featureRepo.readKB(feature);
  if (!kbResult.ok) return kbResult;

  const appendPrompt = [
    '# Feature KB — MANDATORY CONTEXT',
    '',
    'CRITICAL RULES:',
    '- You ALREADY have all the knowledge you need below. Do NOT explore, scan, or investigate the codebase to understand it.',
    '- Do NOT use Glob, Grep, or subagents to discover patterns or architecture — that work has already been done for you.',
    '- ONLY read specific files when you need to edit them.',
    '- Follow the patterns and conventions described in the knowledge below exactly.',
    '',
    '---',
    '',
    kbResult.value,
  ].join('\n');

  const userPrompt = feature.hasSkill
    ? `/${feature.name} ${task}`
    : task;

  const result = await this.claudeClient.execute({
    appendSystemPrompt: appendPrompt,
    userPrompt,
    model,
  });

  if (!result.ok) return result;
  return ok(undefined);
}

function buildDefaultImplementPrompt(): string {
  return [
    '# features implement — default mode',
    '',
    'CRITICAL RULES:',
    '- First inspect the project feature docs under .features/ and choose the smallest relevant feature, if one exists.',
    '- If a relevant feature exists, follow its documented knowledge/skill and update those docs after code changes.',
    '- If no relevant feature exists, implement directly in code with the smallest working change.',
    '- Do not do broad code exploration until feature docs are absent or insufficient.',
  ].join('\n');
}

export class FeatureRepository {
  constructor(private readonly fs: FilesystemRepository) {}

  async findAll(): Promise<Result<Feature[]>> {
    const listResult = await this.fs.listDir('.features');
    if (!listResult.ok) {
      return ok([]);
    }

    const features: Feature[] = [];

    for (const entry of listResult.value) {
      if (!entry.startsWith('features-')) continue;

      const kbPath = join('.features', entry, 'kb', 'KNOWLEDGE.md');
      const legacyKbPath = join('.features', entry, 'kb', 'knowledge.md');
      const legacyKbPath2 = join('.features', entry, 'knowledge', 'knowledge.md');
      const skillPath = join('.features', entry, 'skill', 'SKILL.md');

      const kbExists = await this.fs.exists(kbPath);
      const legacyKbExists = !kbExists && await this.fs.exists(legacyKbPath);
      const legacyKb2Exists = !kbExists && !legacyKbExists && await this.fs.exists(legacyKbPath2);

      if (!kbExists && !legacyKbExists && !legacyKb2Exists) continue;

      const resolvedKbPath = kbExists ? kbPath : legacyKbExists ? legacyKbPath : legacyKbPath2;
      const hasSkill = await this.fs.exists(skillPath);

      features.push({
        name: toFeatureName(entry),
        kbPath: resolvedKbPath,
        skillPath,
        hasSkill,
      });
    }

    return ok(features.sort((a, b) => a.name.localeCompare(b.name)));
  }

  async findByName(name: FeatureName): Promise<Result<Feature>> {
    const featuresResult = await this.findAll();
    if (!featuresResult.ok) return featuresResult;

    const found = featuresResult.value.find((f) => f.name === name);
    if (!found) {
      return fail('FEATURE_NOT_FOUND', `Feature "${name}" not found`);
    }

    return ok(found);
  }

  async readKB(feature: Feature): Promise<Result<string>> {
    return this.fs.readText(feature.kbPath);
  }
}

export class CompileService {
  constructor(
    private readonly fs: FilesystemRepository,
    private readonly git: GitClient,
    private readonly validateService: ValidateService,
  ) {}

  /**
   * md → manifest.json. Pure Node (no AI): parse + validate, verify/heal every code
   * reference against the live repo, extract snippets, compute staleness and stats.
   */
  async compile(): Promise<Result<CompileSummary, FileIssues[] | string>> {
    const project = await this.validateService.validateAll();
    if (!project.ok) return project as Result<never, FileIssues[]>;

    const { overview, features, projectIssues } = project.value;
    const { errors, warnings } = splitIssues(projectIssues);
    if (errors.length > 0) {
      return { ok: false, error: [{ file: `${ANALYSIS_DIR}/`, issues: errors }] };
    }

    // Feature-level staleness: files changed since each feature's analyzedAt sha.
    const changedSince = new Map<string, Set<string>>();
    for (const doc of features.values()) {
      const sha = doc.frontmatter.analyzedAt;
      if (sha && !changedSince.has(sha)) {
        const changed = await this.git.changedFilesSince(sha);
        changedSince.set(sha, new Set(changed.ok ? changed.value : []));
      }
    }

    const counters = { refs: 0, verified: 0, healed: 0, unverified: 0, stale: 0 };
    const staleFeatures: string[] = [];
    const manifestFeatures: ManifestFeature[] = [];
    // Drop related ids whose feature wasn't generated (e.g. a failed analysis pass),
    // so the manifest stays self-consistent instead of carrying dangling links.
    const presentIds = new Set([...features.values()].map((d) => d.frontmatter.id));

    for (const doc of features.values()) {
      const refs: ManifestRef[] = [];
      for (const ref of doc.refs) {
        refs.push(await this.compileRef(ref, counters));
      }

      const changed = doc.frontmatter.analyzedAt ? changedSince.get(doc.frontmatter.analyzedAt) : undefined;
      const featureStale =
        (changed !== undefined && doc.refs.some((r) => changed.has(r.path))) || refs.some((r) => r.stale);
      if (featureStale) staleFeatures.push(doc.frontmatter.id);

      const skillResult = await this.fs.readText(
        join(ANALYSIS_DIR, doc.frontmatter.id, 'skill', 'SKILL.md'),
      );

      manifestFeatures.push({
        id: doc.frontmatter.id,
        area: doc.frontmatter.area,
        name: doc.frontmatter.name,
        summary: doc.frontmatter.summary,
        kind: doc.frontmatter.kind,
        status: doc.frontmatter.status,
        complexity: doc.frontmatter.complexity,
        nutshell: doc.nutshell,
        howItWorks: doc.howItWorks,
        flow: doc.flow,
        files: refs,
        related: doc.frontmatter.related.filter((id) => presentIds.has(id)),
        featureStale,
        skill: skillResult.ok ? skillResult.value : undefined,
      });
    }

    const fileCount = (await this.git.trackedFileCount()) ?? 0;
    const manifest: Manifest = {
      specVersion: SPEC_VERSION,
      repo: {
        name: overview.frontmatter.name,
        tagline: overview.frontmatter.tagline,
        description: overview.description,
        language: overview.frontmatter.language,
        stats: {
          files: fileCount,
          features: manifestFeatures.length,
          areas: overview.areas.length,
          lastAnalyzed: new Date().toISOString(),
        },
      },
      areas: overview.areas,
      features: manifestFeatures,
    };

    const parsed = ManifestSchema.safeParse(manifest);
    if (!parsed.success) {
      return fail2(`Internal error: compiled manifest failed schema validation: ${parsed.error.message}`);
    }

    const writeResult = await this.fs.writeText(MANIFEST_FILE, JSON.stringify(parsed.data, null, 2));
    if (!writeResult.ok) return fail2(writeResult.error.message);

    return ok({
      features: manifestFeatures.length,
      ...counters,
      staleFeatures,
      warnings: warnings.length > 0 ? [{ file: `${ANALYSIS_DIR}/`, issues: warnings }] : [],
      manifestPath: this.fs.resolve(MANIFEST_FILE),
    });
  }

private async compileRef(
  ref: FeatureDoc['refs'][number],
  counters: { refs: number; verified: number; healed: number; unverified: number; stale: number },
): Promise<ManifestRef> {
  counters.refs++;
  const lang = langTagFor(ref.path);
  const base = { path: ref.path, lang, what: ref.what, annotation: ref.note, symbol: ref.symbol };

  const source = await this.fs.readText(ref.path);
  if (!source.ok) {
    counters.stale++;
    return {
      ...base,
      lines: ref.lines,
      code: '',
      provenance: 'stale',
      verifiedBy: 'none',
      healed: false,
      stale: true,
      staleReason: 'file-missing',
    };
  }

  const outcome = await verifyRef(source.value, ref);
  counters[
    outcome.provenance === 'verified'
      ? 'verified'
      : outcome.provenance === 'healed'
        ? 'healed'
        : outcome.provenance === 'stale'
          ? 'stale'
          : 'unverified'
  ]++;

  return {
    ...base,
    lines: outcome.lines,
    code: extractSnippet(source.value, outcome.lines),
    provenance: outcome.provenance,
    verifiedBy: outcome.verifiedBy,
    healed: outcome.healed,
    stale: outcome.stale,
    staleReason: outcome.staleReason,
  };
}

export async function verifyRef(source: string, ref: CodeRef): Promise<VerifyOutcome> {
  const sourceLines = source.split('\n');
  const totalLines = sourceLines.length;
  const authored = ref.lines;

  if (authored.start > totalLines) {
    // Range is entirely beyond EOF; clamp so the viewer can still show *something*.
    return {
      lines: clamp(authored, totalLines),
      provenance: 'stale',
      verifiedBy: 'none',
      healed: false,
      stale: true,
      staleReason: 'lines-out-of-range',
    };
  }

  if (!ref.symbol) {
    return {
      lines: clamp(authored, totalLines),
      provenance: 'unverified',
      verifiedBy: 'none',
      healed: false,
      stale: false,
    };
  }

  // --- tree-sitter pass ---
  const declarations = await collectDeclarations(source, ref.path);
  if (declarations) {
    const match = matchSymbol(declarations, ref.symbol, authored);
    if (match) {
      if (stillAccurate(authored, match.range)) {
        // Authored range still points at (or into) the right declaration.
        return {
          lines: clamp(authored, totalLines),
          provenance: 'verified',
          verifiedBy: 'tree-sitter',
          healed: false,
          stale: false,
        };
      }
      // Code moved: heal to the resolved declaration range.
      return {
        lines: match.range,
        provenance: 'healed',
        verifiedBy: 'tree-sitter',
        healed: true,
        stale: false,
      };
    }
    // Grammar parsed the file but no declaration matches — the symbol may be a call
    // site or was removed. Try grep before declaring it stale.
  }

  // --- grep fallback ---
  const hits = grepLines(sourceLines, ref.symbol);
  if (hits.length > 0) {
    const inRange = hits.some((line) => line >= authored.start && line <= authored.end);
    if (inRange) {
      return {
        lines: clamp(authored, totalLines),
        provenance: 'verified',
        verifiedBy: 'grep',
        healed: false,
        stale: false,
      };
    }
    // Heal: keep the authored window size, repositioned at the first occurrence.
    const span = authored.end - authored.start;
    const start = hits[0]!;
    return {
      lines: clamp({ start, end: start + span }, totalLines),
      provenance: 'healed',
      verifiedBy: 'grep',
      healed: true,
      stale: false,
    };
  }

  return {
    lines: clamp(authored, totalLines),
    provenance: 'stale',
    verifiedBy: 'none',
    healed: false,
    stale: true,
    staleReason: 'symbol-not-found',
  };
}

export class ValidateService {
  constructor(private readonly fs: FilesystemRepository) {}

  /** List feature md files (repo-relative paths), excluding underscore-prefixed artifacts. */
  async listFeatureFiles(): Promise<Result<string[]>> {
    const entries = await this.fs.listDir(ANALYSIS_FEATURES_DIR);
    if (!entries.ok) return entries;
    return ok(
      entries.value
        .filter((name) => name.endsWith('.md') && !name.startsWith('_'))
        .sort()
        .map((name) => `${ANALYSIS_FEATURES_DIR}/${name}`),
    );
  }

  /**
   * Parse and validate the whole .features/ directory.
   * Returns the parsed project, or every issue found (grouped by file).
   */
  async validateAll(): Promise<Result<ValidatedProject, FileIssues[]>> {
    const allIssues: FileIssues[] = [];

    if (!(await this.fs.exists(OVERVIEW_FILE))) {
      return fail2([{ file: OVERVIEW_FILE, issues: [issue('not-initialized', 'overview.md not found — run `features init` first')] }]);
    }

    const overviewSource = await this.fs.readText(OVERVIEW_FILE);
    if (!overviewSource.ok) {
      return fail2([{ file: OVERVIEW_FILE, issues: [issue('read-error', overviewSource.error.message)] }]);
    }
    const overviewResult = parseOverview(overviewSource.value);
    if (!overviewResult.ok) {
      allIssues.push({ file: OVERVIEW_FILE, issues: overviewResult.issues });
    }

    const fileList = await this.listFeatureFiles();
    const features = new Map<string, FeatureDoc>();
    if (fileList.ok) {
      for (const file of fileList.value) {
        const source = await this.fs.readText(file);
        if (!source.ok) {
          allIssues.push({ file, issues: [issue('read-error', source.error.message)] });
          continue;
        }
        const result = parseFeature(source.value);
        if (!result.ok) {
          allIssues.push({ file, issues: result.issues });
          continue;
        }
        // id must match filename
        const expectedId = file.split('/').pop()!.replace(/\.md$/, '');
        if (result.doc.frontmatter.id !== expectedId) {
          allIssues.push({
            file,
            issues: [issue('id-mismatch', `Frontmatter id "${result.doc.frontmatter.id}" must equal filename "${expectedId}"`)],
          });
          continue;
        }
        features.set(file, result.doc);
      }
    }

    if (!overviewResult.ok || allIssues.length > 0) {
      return fail2(allIssues);
    }

    const projectIssues = validateProject(overviewResult.doc, [...features.values()]);
    return ok({ overview: overviewResult.doc, features, projectIssues });
  }
}

export const ManifestRefSchema = z.object({
  path: z.string().min(1),
  /** Language tag for syntax highlighting, inferred from the extension. */
  lang: z.string(),
  what: z.string(),
  annotation: z.string().optional(),
  /** The range the snippet was extracted from (post-healing). */
  lines: LineRangeSchema,
  symbol: z.string().optional(),
  /** Extracted at compile time from the live repo — never authored. */
  code: z.string(),
  provenance: RefProvenanceSchema,
  verifiedBy: z.enum(['tree-sitter', 'grep', 'none']),
  /** True when the authored range drifted and was auto-corrected via symbol resolution. */
  healed: z.boolean(),
  stale: z.boolean(),
  staleReason: StaleReasonSchema.optional(),
});

export const FeatureDocSchema = z.object({
  frontmatter: FeatureFrontmatterSchema,
  nutshell: z.string().min(1),
  howItWorks: z.array(z.string().min(1)).min(1),
  flow: z.array(FlowStepSchema),
  refs: z.array(CodeRefSchema).min(1),
});

export type FeatureDoc = z.infer<typeof FeatureDocSchema>;

export function makeInitCommand(deps: InitDeps) {
  const { analyzeService, compileService, gitClient, fs, rootDir } = deps;

  return async function initCommand(options: InitOptions): Promise<void> {
    showAnalyzeIntro('init');
    await migrateFromCodeExplain(fs);
    const model = resolveModel(options.model, 'claude-opus-4-6');
    showInfo(`Model: ${model}`);
    const useCache = options.cache !== false;
    analyzeService.resetStats();

    let inventory: InventoryEntry[] = [];

    if (options.feature) {
      const existing = await analyzeService.readInventory();
      if (!existing.ok) {
        showError(existing.error.message);
        process.exitCode = 1;
        return;
      }
      const entry = existing.value.find((e) => e.id === options.feature);
      if (!entry) {
        showError(`Feature "${options.feature}" is not in the inventory. Known ids: ${existing.value.map((e) => e.id).join(', ')}`);
        process.exitCode = 1;
        return;
      }
      inventory = [entry];
    } else {
      let resumed = false;
      if (useCache) {
        const existing = await analyzeService.readInventory();
        if (existing.ok) {
          inventory = existing.value;
          resumed = true;
          showSuccess(`Resuming from previous inventory (${inventory.length} features). Use --no-cache to re-discover.`);
        }
      }

      if (!resumed) {
        while (true) {
          const ac = new AbortController();
          const sigintHandler = () => { ac.abort(); };
          process.on('SIGINT', sigintHandler);

          const spin = createSpinner();
          spin.start('Pass 1/2 — discovering areas and features…');
          const result = await analyzeService.runInventory(model, QUIET, ac.signal);

          process.off('SIGINT', sigintHandler);

          if (result.ok) {
            spin.stop('Inventory complete.');
            inventory = result.value;
            showSuccess(`Inventory: ${inventory.length} feature(s) across the repo.`);
            break;
          }
          if (result.error.code === 'CLAUDE_ABORTED') {
            spin.stop('Paused.');
            showInfo('Press Enter to resume (Ctrl+C to exit)…');
            await waitForEnterOrExit();
            showInfo('Retrying inventory…');
            continue;
          }
          if (result.error.code === 'CLAUDE_RATE_LIMITED') {
            spin.stop('Quota reached.');
            showWarn(`Usage limit reached: ${result.error.message}`);
            showInfo('Press Enter to retry when your quota resets (Ctrl+C to exit)…');
            await waitForEnterOrExit();
            showInfo('Retrying inventory…');
            continue;
          }
          // Genuine failure — surface it and stop, rather than looping as if it were a quota reset.
          spin.stop('Failed.');
          showError(`Inventory failed: ${result.error.message}`);
          process.exitCode = 1;
          return;
        }
      }

async runInventory(model: ClaudeModel, onProgress?: ProgressObserver, signal?: AbortSignal): Promise<Result<InventoryEntry[]>> {
  if (!(await this.git.isRepo())) {
    return fail('ANALYSIS_FAILED', 'Not a git repository — features init needs git for staleness tracking.');
  }
  const sha = await this.git.headSha();
  if (!sha.ok) return sha;

  const featureDirResult = await this.fs.ensureDir(ANALYSIS_FEATURES_DIR);
  if (!featureDirResult.ok) return featureDirResult;
  const skillDirResult = await this.fs.ensureDir(SKILLS_DIR);
  if (!skillDirResult.ok) return skillDirResult;

  const fileCount = (await this.git.trackedFileCount()) ?? 0;
  const hasCodegraph = await this.fs.exists('.codegraph');

  const overviewPath = this.abs(OVERVIEW_FILE);
  const inventoryPath = this.abs(INVENTORY_FILE);
  const mapContext = this.repoMap ? buildInventoryContext(this.repoMap) : '';
  const userPrompt = [
    `Analyze the repository at the current working directory.`,
    ``,
    `Write your two deliverables to exactly these absolute paths:`,
    `1. ${overviewPath}`,
    `2. ${inventoryPath}`,
    this.PATH_GUARD,
    ``,
    `Use this git sha as analyzedAt: ${sha.value}`,
    ``,
    budgetHint(fileCount),
    featureCountHint(fileCount),
    ...(mapContext ? ['', mapContext] : []),
  ].join('\n');

  const run = await this.claude.execute({
    systemPromptFile: INVENTORY_PROMPT_PATH,
    userPrompt,
    model,
    print: true,
    cwd: this.fs.root,
    onEvent: this.claudeObserver(onProgress),
    // Stable across all feature calls → preserves Claude prompt-cache hits. Per-feature context goes in userPrompt.
    appendSystemPrompt: hasCodegraph ? CODEGRAPH_ADDENDUM : undefined,
    signal,
  });
  if (!run.ok) return run;
  this.trackCall(run.value);

  // Validate both outputs; one focused repair turn on failure.
  for (let attempt = 0; ; attempt++) {
    const problems = await this.inventoryProblems();
    if (problems.length === 0) break;
    if (attempt >= MAX_REPAIRS) {
      return fail('ANALYSIS_FAILED', `Inventory output is invalid after ${MAX_REPAIRS} repairs:\n${problems.join('\n')}`);
    }
    onProgress?.({ kind: 'warn', message: `Inventory has ${problems.length} validation problem(s) — repairing…` });
    const repair = await this.claude.execute({
      systemPromptFile: INVENTORY_PROMPT_PATH,
      userPrompt: [
        `Your previous output in ${overviewPath} and ${inventoryPath} has validation errors.`,
        `Fix the files in place. Errors:`,
        ...problems.map((p) => `- ${p}`),
      ].join('\n'),
      model,
      print: true,
      cwd: this.fs.root,
      onEvent: this.claudeObserver(onProgress),
      signal,
    });
    if (!repair.ok) return repair;
    this.trackCall(repair.value, true);
  }

  return this.readInventory();
}

async runCombinedFeature(entry: InventoryEntry, model: ClaudeModel, onProgress?: ProgressObserver, signal?: AbortSignal, settingsJson?: string): Promise<Result<void>> {
  const sha = await this.git.headSha();
  if (!sha.ok) return sha;

  const hasCodegraph = await this.fs.exists('.codegraph');
  const maxTurns = turnCapFor(entry.complexity);

  const featureFile = `${ANALYSIS_FEATURES_DIR}/${entry.id}.md`;
  const absFeatureFile = this.abs(featureFile);
  const skillFile = `${SKILLS_DIR}/${entry.id}.md`;
  const featureContext = this.repoMap
    ? await buildFeatureContext(entry, this.repoMap, async (p) => {
        const r = await this.fs.readText(p);
        return r.ok ? r.value : undefined;
      })
    : '';
  const userPrompt = [
    `Deep-dive the ${entry.kind} feature "${entry.name}" (id: ${entry.id}) of this repository.`,
    `It belongs to area "${entry.area}". Its one-line summary from the inventory:`,
    `"${entry.summary}"`,
    ``,
    `Write the feature knowledge file to exactly this absolute path: ${absFeatureFile}`,
    this.PATH_GUARD,
    `Use this git sha for analyzedAt and every ref's sha field: ${sha.value}`,
    ``,
    `Feature ids that exist (for the related list): see ${this.abs(INVENTORY_FILE)}.`,
    ...(featureContext ? ['', featureContext] : []),
  ].join('\n');

  const run = await this.claude.execute({
    systemPromptFile: COMBINED_PROMPT_PATH,
    userPrompt,
    model,
    print: true,
    cwd: this.fs.root,
    onEvent: this.claudeObserver(onProgress),
    // Stable across all feature calls → preserves Claude prompt-cache hits. Per-feature context goes in userPrompt.
    appendSystemPrompt: hasCodegraph ? CODEGRAPH_ADDENDUM : undefined,
    signal,
    maxTurns,
    settingsJson,
  });
  if (!run.ok) return run;
  this.trackCall(run.value);

  // Generate skill deterministically from the parsed knowledge file
  await this.renderAndWriteSkill(entry, featureFile, skillFile);

  for (let attempt = 0; ; attempt++) {
    const featureIssues = await this.featureProblems(featureFile, entry);
    if (featureIssues.length === 0) {
      // Re-render skill after a successful repair (knowledge file just changed)
      await this.renderAndWriteSkill(entry, featureFile, skillFile);
      return ok(undefined);
    }

    const allProblems = featureIssues.map(
      (i) => `${absFeatureFile}: ${i.code}: ${i.message}${i.line !== undefined ? ` (line ${i.line})` : ''}`,
    );

    if (attempt >= MAX_REPAIRS) {
      return fail(
        'ANALYSIS_FAILED',
        `${entry.id} is invalid after ${MAX_REPAIRS} repairs:\n${allProblems.map((p) => `- ${p}`).join('\n')}`,
      );
    }
    onProgress?.({ kind: 'warn', message: `${entry.id} has ${featureIssues.length} validation problem(s) — repairing…` });
    const repair = await this.claude.execute({
      systemPromptFile: COMBINED_PROMPT_PATH,
      userPrompt: [
        `Your previous output at ${absFeatureFile} has validation errors. Fix the file in place. Errors:`,
        ...allProblems.map((p) => `- ${p}`),
      ].join('\n'),
      model,
      print: true,
      cwd: this.fs.root,
      onEvent: this.claudeObserver(onProgress),
      signal,
    });
    if (!repair.ok) return repair;
    this.trackCall(repair.value, true);
  }
}

export async function buildRepoMapFromFiles(sources: Map<string, string>): Promise<RepoMap> {
  const known = new Set(sources.keys());
  const files: FileEntry[] = [];
  const symbolIndex = new Map<string, string[]>();

  for (const [path, source] of sources) {
    const decls = (await collectDeclarations(source, path)) ?? [];
    const symbols = [...new Set(decls.filter((d) => d.ancestry.length === 0).map((d) => d.name))];

    const specifiers = extractImportSpecifiers(source, path);
    const imports = [...new Set(specifiers.map((s) => resolveSpecifier(s, path, known)).filter((p): p is string => !!p))];

    files.push({ path, symbols, imports });
    for (const sym of symbols) {
      const arr = symbolIndex.get(sym) ?? [];
      arr.push(path);
      symbolIndex.set(sym, arr);
    }
  }
  return { files, symbolIndex };
}

export async function buildRepoMap(root: string, trackedFiles: readonly string[]): Promise<RepoMap> {
  const sources = new Map<string, string>();
  for (const rel of trackedFiles) {
    if (isIgnored(rel)) continue;
    if (!grammarFor(rel)) continue;
    try {
      const buf = await readFile(join(root, rel));
      if (buf.byteLength > MAX_FILE_BYTES) continue;
      sources.set(rel.replace(/\\/g, '/'), buf.toString('utf-8'));
    } catch {
      // unreadable — skip
    }
  }
  return buildRepoMapFromFiles(sources);
}

export function buildInventoryContext(map: RepoMap): string {
  const lines: string[] = ['## Repository map (pre-computed — use instead of scanning)', ''];
  for (const f of map.files) {
    const syms = f.symbols.slice(0, 12).join(', ');
    lines.push(`- ${f.path}${syms ? ` — ${syms}` : ''}`);
    if (lines.join('\n').length > INVENTORY_MAP_CAP) {
      lines.push(`- … (${map.files.length} files total; map truncated)`);
      break;
    }
  }
  return lines.join('\n');
}

export function makeServeCommand(deps: ServeDeps) {
  const { serveService, liveServerService } = deps;

  return async function serveCommand(options: ServeOptions): Promise<void> {
    showAnalyzeIntro(options.live ? 'serve --live' : 'serve');

    const port = Number(options.port ?? DEFAULT_SERVE_PORT);
    const result = options.live
      ? liveServerService.start(port, resolveModel(options.model, 'sonnet'))
      : serveService.start(port);
    if (!result.ok) {
      showError(result.error.message);
      process.exitCode = 1;
      return;
    }

    showInfo(`Browsing at ${chalk.bold(`http://localhost:${port}`)} — press Ctrl-C to stop.`);
    if (options.live) showInfo('Live mode: trigger re-analysis from the UI.');
  };
}

export class ServeService {
  constructor(
    private readonly fs: FilesystemRepository,
    private readonly viewerDistDir: string,
  ) {}

  /** Serve the bundled viewer + the repo's manifest.json on the given port. */
  start(port: number): Result<Server> {
    if (!existsSync(join(this.viewerDistDir, 'index.html'))) {
      return fail(
        'SERVER_ERROR',
        `Viewer assets not found at ${this.viewerDistDir}. Reinstall features CLI.`,
      );
    }
    if (!this.fs.existsSync(MANIFEST_FILE)) {
      return fail('SERVER_ERROR', 'manifest.json not found — run `features init` first.');
    }

    const server = createServer((req, res) => this.handle(req, res));
    server.listen(port);
    return ok(server);
  }

  private handle(req: IncomingMessage, res: ServerResponse): void {
    const url = (req.url ?? '/').split('?')[0]!;

    if (url === '/manifest.json') {
      this.sendFile(res, this.fs.resolve(MANIFEST_FILE));
      return;
    }

    const docMatch = url.match(/^\/api\/doc\/([a-z0-9-]+)\/(feature|skill)$/);
    if (docMatch) {
      const docPath = this.docPath(docMatch[1]!, docMatch[2]!);
      if (docPath) this.sendFile(res, docPath);
      else {
        res.statusCode = 404;
        res.end('Not found');
      }
      return;
    }

    const skillMatch = url.match(/^\/api\/skill\/([a-z0-9-]+)$/);
    if (skillMatch) {
      const skillPath = this.docPath(skillMatch[1]!, 'skill');
      if (skillPath) this.sendFile(res, skillPath);
      else {
        res.statusCode = 404;
        res.end('Not found');
      }
      return;
    }

    // Static viewer assets; anything unknown falls back to index.html (SPA).
    const safePath = normalize(url).replace(/^(\.\.[/\\])+/, '');
    const assetPath = join(this.viewerDistDir, safePath === '/' ? 'index.html' : safePath);
    if (assetPath.startsWith(this.viewerDistDir) && existsSync(assetPath) && statSync(assetPath).isFile()) {
      this.sendFile(res, assetPath);
      return;
    }
    this.sendFile(res, join(this.viewerDistDir, 'index.html'));
  }

  private docPath(featureId: string, kind: string): string | undefined {
    if (kind === 'feature') return this.fs.resolve(join(ANALYSIS_FEATURES_DIR, `${featureId}.md`));
    const flat = this.fs.resolve(join(SKILLS_DIR, `${featureId}.md`));
    const nested = this.fs.resolve(join(ANALYSIS_DIR, featureId, 'skill', 'SKILL.md'));
    return existsSync(flat) ? flat : existsSync(nested) ? nested : undefined;
  }

  private sendFile(res: ServerResponse, path: string): void {
    res.setHeader('Content-Type', MIME[extname(path)] ?? 'application/octet-stream');
    res.setHeader('Cache-Control', 'no-cache');
    createReadStream(path)
      .on('error', () => {
        res.statusCode = 404;
        res.end('Not found');
      })
      .pipe(res);
  }
}

export class LiveServerService {
  private listeners = new Set<Listener>();
  private running = false;
  private runId = 0;
  private log: LiveEvent[] = [];

  constructor(
    private readonly fs: FilesystemRepository,
    private readonly analyzeService: AnalyzeService,
    private readonly compileService: CompileService,
    private readonly viewerDistDir: string,
  ) {}

  start(port: number, model: ClaudeModel): Result<ServerType> {
    if (!existsSync(join(this.viewerDistDir, 'index.html'))) {
      return fail('SERVER_ERROR', `Viewer assets not found at ${this.viewerDistDir}.`);
    }

    const app = new Hono();

    app.get('/manifest.json', async (c) => {
      const manifest = await this.fs.readText(MANIFEST_FILE);
      if (!manifest.ok) return c.json({ error: 'No manifest — run an analysis first.' }, 404);
      return c.body(manifest.value, 200, { 'Content-Type': 'application/json' });
    });

    app.get('/api/skill/:featureId', async (c) => {
      const featureId = c.req.param('featureId');
      if (!/^[a-z0-9-]+$/.test(featureId)) return c.text('Bad request', 400);
      const nested = await this.fs.readText(join(ANALYSIS_DIR, featureId, 'skill', 'SKILL.md'));
      if (nested.ok) return c.text(nested.value, 200, { 'Content-Type': 'text/plain; charset=utf-8' });
      const flat = await this.fs.readText(join(ANALYSIS_DIR, 'skills', `${featureId}.md`));
      if (flat.ok) return c.text(flat.value, 200, { 'Content-Type': 'text/plain; charset=utf-8' });
      return c.text('Not found', 404);
    });

    app.get('/api/doc/:featureId/:kind', async (c) => {
      const path = this.docPath(c.req.param('featureId'), c.req.param('kind'));
      if (!path) return c.text('Bad request', 400);
      const doc = await this.fs.readText(path);
      return doc.ok ? c.text(doc.value, 200, { 'Content-Type': 'text/plain; charset=utf-8' }) : c.text('Not found', 404);
    });

    app.put('/api/doc/:featureId/:kind', async (c) => {
      if (this.running) return c.json({ error: 'Analysis is running; try again when it finishes.' }, 409);
      const path = this.docPath(c.req.param('featureId'), c.req.param('kind'));
      if (!path) return c.json({ error: 'Bad request' }, 400);
      const body = (await c.req.json().catch(() => ({}))) as { content?: unknown };
      if (typeof body.content !== 'string') return c.json({ error: 'Missing content.' }, 400);

      const old = await this.fs.readText(path);
      const written = await this.fs.writeText(path, body.content);
      if (!written.ok) return c.json({ error: written.error.message }, 500);

      if (c.req.param('kind') === 'feature') {
        const compiled = await this.compileService.compile();
        if (!compiled.ok) {
          if (old.ok) await this.fs.writeText(path, old.value);
          return c.json({ error: typeof compiled.error === 'string' ? compiled.error : 'Compile failed — spec violations.' }, 400);
        }
      }

      return c.json({ ok: true });
    });

    app.get('/api/status', (c) =>
      c.json({ live: true, analyzing: this.running, runId: this.runId, hasManifest: this.fs.existsSync(MANIFEST_FILE) }),
    );

    app.post('/api/analyze', async (c) => {
      if (this.running) return c.json({ error: 'An analysis is already running.', runId: this.runId }, 409);
      const body = (await c.req.json().catch(() => ({}))) as { feature?: string };
      this.runId += 1;
      this.log = [];
      void this.runAnalysis(model, body.feature); // fire and forget; progress flows over SSE
      return c.json({ runId: this.runId });
    });

    app.get('/api/analyze/events', (c) =>
      streamSSE(c, async (stream) => {
        // Replay the current run's log so late subscribers see full history.
        for (const event of this.log) {
          await stream.writeSSE({ event: event.kind, data: JSON.stringify(event) });
        }
        const listener: Listener = (event) => {
          void stream.writeSSE({ event: event.kind, data: JSON.stringify(event) });
        };
        this.listeners.add(listener);
        stream.onAbort(() => {
          this.listeners.delete(listener);
        });
        // Keep the connection open until the client disconnects.
        await new Promise<void>((resolve) => stream.onAbort(resolve));
      }),
    );

    app.use('/*', serveStatic({ root: this.viewerDistDir }));
    app.notFound(async (c) => {
      const index = await this.fs.readText(join(this.viewerDistDir, 'index.html'));
      return index.ok ? c.html(index.value) : c.text('Not found', 404);
    });

    return ok(serve({ fetch: app.fetch, port }));
  }

  private docPath(featureId: string, kind: string): string | undefined {
    if (!/^[a-z0-9-]+$/.test(featureId)) return undefined;
    if (kind === 'feature') return join(ANALYSIS_FEATURES_DIR, `${featureId}.md`);
    if (kind === 'skill') return join(SKILLS_DIR, `${featureId}.md`);
    return undefined;
  }

  private emit(event: ProgressEvent & { kind: ProgressEvent['kind'] | 'done' | 'error' }): void {
    const live = { ...event, runId: this.runId } as LiveEvent;
    this.log.push(live);
    for (const listener of this.listeners) listener(live);
  }

  private async runAnalysis(model: ClaudeModel, featureId?: string): Promise<void> {
    this.running = true;
    const onProgress = (e: ProgressEvent) => this.emit(e);
    try {
      let inventory;
      if (featureId) {
        const existing = await this.analyzeService.readInventory();
        if (!existing.ok) return this.emit({ kind: 'error' as never, message: existing.error.message });
        const entry = existing.value.find((e) => e.id === featureId);
        if (!entry) return this.emit({ kind: 'error' as never, message: `Unknown feature "${featureId}".` });
        inventory = [entry];
      } else {
        this.emit({ kind: 'phase', message: 'Pass 1/2 — discovering areas and features…' });
        const result = await this.analyzeService.runInventory(model, onProgress);
        if (!result.ok) return this.emit({ kind: 'error' as never, message: result.error.message });
        inventory = result.value;
        this.emit({ kind: 'phase', message: `Inventory: ${inventory.length} feature(s).` });
      }

      for (let i = 0; i < inventory.length; i++) {
        const entry = inventory[i]!;
        this.emit({ kind: 'phase', message: `Pass 2/2 — [${i + 1}/${inventory.length}] ${entry.name}…` });
        const result = await this.analyzeService.runDeepDive(entry, model, onProgress);
        if (!result.ok) this.emit({ kind: 'warn', message: `${entry.id}: ${result.error.message}` });
      }

      this.emit({ kind: 'phase', message: 'Compiling manifest…' });
      const compiled = await this.compileService.compile();
      if (!compiled.ok) {
        return this.emit({
          kind: 'error' as never,
          message: typeof compiled.error === 'string' ? compiled.error : 'Compile failed — spec violations.',
        });
      }
      const s = compiled.value;
      this.emit({
        kind: 'done' as never,
        message: `Compiled ${s.features} feature(s) — ${s.verified} verified, ${s.healed} healed, ${s.stale} stale.`,
      });
    } finally {
      this.running = false;
    }
  }
}

