export const FEATURE_SKILL_PROMPT_PATH = join(PROMPTS_DIR, 'FEATURE-SKILL.md');
export const COMBINED_PROMPT_PATH = join(PROMPTS_DIR, 'FEATURE-COMBINED.md');
